/* Calcetto dashboard - single-page app with hash routing.
 * Data comes from data/derived/data.js (window.CALCETTO), generated by
 * scripts/build_stats.py. No external libraries.
 */
(function () {
  "use strict";

  const D = window.CALCETTO;
  const $app = document.getElementById("app");

  // ---------- constants ----------
  const MIN_SYNERGY = 3;          // matches together before a synergy is "significant"
  const COLORS = {
    gol: "#5aa832", assist: "#a86ee0",          // validated pair (dark surface)
    fatti: "#2e9e8f", subiti: "#d9534f",        // validated pair + direction encoding
    teamA: "#4c8dff", teamB: "#d0661a",         // defaults when no colour is set
  };
  // Team colours selectable per match (partite.colore_A / colore_B).
  const TEAM_PALETTE = {
    rosso: "#d9443f", blu: "#3f7fe0", azzurro: "#3fb6e0", verde: "#3a9e5c",
    giallo: "#e0b23f", arancio: "#d0661a", viola: "#9b5de5", bianco: "#e8ecf7",
    nero: "#5b6378", grigio: "#8b96bd",
  };
  const ROLES = {
    P: ["Portiere", "POR"], D: ["Difensore", "DIF"], MS: ["Mediano sinistro", "MS"],
    MD: ["Mediano destro", "MD"], A: ["Attaccante", "ATT"],
  };
  const ROLE_ORDER = ["P", "D", "MS", "MD", "A"];
  const roleName = (r) => (ROLES[r] ? ROLES[r][0] : r || "—");
  const roleShort = (r) => (ROLES[r] ? ROLES[r][1] : r || "");

  // ---------- data prep ----------
  const toInt = (v) => (v === "" || v == null ? 0 : Number(v));
  const players = new Map(D.giocatori.map((p) => [p.id_giocatore, p]));
  const matches = [...D.partite].sort((a, b) => a.data.localeCompare(b.data) || a.id_partita.localeCompare(b.id_partita));
  const matchById = new Map(matches.map((m) => [m.id_partita, m]));
  const apps = D.presenze.map((a) => ({
    ...a,
    gol: toInt(a.gol), assist: toInt(a.assist), autogol: toInt(a.autogol),
    parate_miracolose: toInt(a.parate_miracolose),
    pali_traverse: a.pali_traverse === "" ? null : toInt(a.pali_traverse),
    gol_squadra: toInt(a.gol_squadra), gol_subiti: toInt(a.gol_subiti),
  }));
  const seasons = [...new Set(matches.map((m) => m.stagione))].sort();
  let season = seasons[seasons.length - 1] || "";

  const seasonMatches = () => matches.filter((m) => m.stagione === season);
  const seasonApps = () => apps.filter((a) => a.stagione === season);
  const standings = () => D.classifica.filter((r) => r.stagione === season);
  const appsOf = (pid) => seasonApps().filter((a) => a.id_giocatore === pid)
    .sort((a, b) => a.data.localeCompare(b.data));
  const appsOfMatch = (mid) => apps.filter((a) => a.id_partita === mid);

  // ---------- helpers ----------
  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const fullName = (p) => `${p.nome} ${p.cognome}`;
  const initials = (p) => (p.nome[0] || "") + (p.cognome[0] || "");
  const fmtDate = (iso, opts) => new Date(iso + "T12:00:00").toLocaleDateString("it-IT",
    opts || { weekday: "short", day: "numeric", month: "short", year: "numeric" });
  const shortDate = (iso) => fmtDate(iso, { day: "2-digit", month: "2-digit" });
  const pct = (a, b) => (b ? Math.round((100 * a) / b) : 0);
  const fmt1 = (x) => (Math.round(x * 100) / 100).toLocaleString("it-IT");
  const teamName = (m, t) => m["squadra_" + t] || "Squadra " + t;
  const teamColor = (m, t) => TEAM_PALETTE[(m["colore_" + t] || "").toLowerCase()] || (t === "A" ? COLORS.teamA : COLORS.teamB);
  const teamDot = (m, t, extra = "") => `<span class="dot" style="background:${teamColor(m, t)};${extra}"></span>`;
  const crestLetter = (m, t) => { const w = teamName(m, t).trim().split(/\s+/); return (w[w.length - 1][0] || t).toUpperCase(); };
  const nick = (p, cls = "who-nick") => (p.soprannome ? `<div class="${cls}">“${esc(p.soprannome)}”</div>` : "");
  const matchNo = (m) => seasonMatchesOf(m.stagione).indexOf(m) + 1;
  const seasonMatchesOf = (s) => matches.filter((m) => m.stagione === s);

  function avatar(p, cls = "") {
    const gk = p.ruolo_abituale === "P" ? " gk" : "";
    const img = p.foto ? `<img src="${esc(p.foto)}" alt="" onerror="this.remove()">` : "";
    return `<span class="av${gk} ${cls}">${esc(initials(p))}${img}</span>`;
  }
  function who(p, sub) {
    return `<span class="who">${avatar(p)}<span><span class="who-name">${esc(fullName(p))}</span>${
      sub || p.soprannome ? `<br><span class="who-nick">${esc(sub || "“" + p.soprannome + "”")}</span>` : ""}</span></span>`;
  }
  const chip = (e, lg) => `<span class="chip ${e}${lg ? " lg" : ""}" title="${{ V: "Vittoria", X: "Pareggio", S: "Sconfitta" }[e]}">${{ V: "V", X: "P", S: "S" }[e]}</span>`;
  const form = (pid, n = 5) => `<span class="form">${appsOf(pid).slice(-n).map((a) => chip(a.esito)).join("")}</span>`;

  const ICON = {
    ball: `<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#fff"/><path d="M12 7l4 3-1.5 4.5h-5L8 10z" fill="#111"/><path d="M12 2v5M16 10l5-2M14.5 14.5l3 4.5M9.5 14.5l-3 4.5M8 10L3 8" stroke="#111" stroke-width="1.2" fill="none"/></svg>`,
    ogball: `<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10" fill="#e5484d"/><path d="M12 7l4 3-1.5 4.5h-5L8 10z" fill="#fff"/></svg>`,
  };
  // Single source for per-match stats, used by pitch badges, tooltips and
  // tables so they always show the same items, icons and numbers.
  const STAT_DEFS = [
    ["gol", "⚽", "Gol"], ["assist", "👟", "Assist"], ["parate_miracolose", "🧤", "Parate miracolose"],
    ["autogol", "🔴", "Autogol"], ["pali_traverse", "🥅", "Pali e traverse"],
  ];
  const statList = (a) => STAT_DEFS.filter(([k]) => a[k] > 0).map(([k, icon, label]) => ({ k, icon, label, n: a[k] }));
  const statIcons = (a) => statList(a)
    .map((s) => `<span class="ic${s.k === "autogol" ? " og" : ""}" title="${s.label}">${s.icon}${s.n}</span>`).join("");
  const statTooltip = (a, p) => `<b>${esc(fullName(p))}</b>${p.soprannome ? ` <span class="muted">“${esc(p.soprannome)}”</span>` : ""}
    <div class="tt-row"><span>Ruolo</span><span>${roleName(a.ruolo)}</span></div>
    ${statList(a).map((s) => `<div class="tt-row"><span>${s.icon} ${s.label}</span><span>${s.n}</span></div>`).join("") || `<div class="tt-row"><span>Nessuna statistica</span></div>`}`;

  // ---------- tooltip ----------
  const tt = document.createElement("div");
  tt.className = "tooltip";
  document.body.appendChild(tt);
  function bindTooltips(root) {
    root.querySelectorAll("[data-tt]").forEach((el) => {
      el.addEventListener("mousemove", (e) => {
        tt.innerHTML = el.getAttribute("data-tt");
        tt.style.opacity = 1;
        const w = tt.offsetWidth;
        tt.style.left = Math.min(e.clientX + 14, window.innerWidth - w - 10) + "px";
        tt.style.top = e.clientY + 14 + "px";
      });
      el.addEventListener("mouseleave", () => (tt.style.opacity = 0));
    });
  }

  // ---------- charts (hand-made SVG) ----------
  // Bar path with 4px rounded data-end, anchored square to the baseline.
  function barPath(x, y0, w, h, up) {
    if (h <= 0) return "";
    const r = Math.min(4, w / 2, h);
    if (up) {
      const y = y0 - h;
      return `M${x},${y0}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y0}Z`;
    }
    const y = y0 + h;
    return `M${x},${y0}V${y - r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y - r}V${y0}Z`;
  }
  function niceMax(v) { return v <= 4 ? 4 : v <= 6 ? 6 : v <= 8 ? 8 : v <= 10 ? 10 : Math.ceil(v / 5) * 5; }

  // Grouped bars. series: [{name,color,values}], cats: [{label, tt}]
  function groupedBars(cats, series, opts = {}) {
    const W = 640, H = opts.height || 220, m = { t: 12, r: 8, b: 26, l: 28 };
    const iw = W - m.l - m.r, ih = H - m.t - m.b;
    const max = niceMax(Math.max(1, ...series.flatMap((s) => s.values)));
    const y = (v) => m.t + ih - (v / max) * ih;
    const band = iw / Math.max(cats.length, 1);
    const bw = Math.min(26, (band * 0.7) / series.length);
    const step = max <= 10 ? (max <= 6 ? 1 : 2) : 5;
    let g = "";
    for (let v = 0; v <= max; v += step) {
      g += `<line class="${v ? "gridline" : "axis"}" x1="${m.l}" x2="${W - m.r}" y1="${y(v)}" y2="${y(v)}"/>`;
      g += `<text x="${m.l - 6}" y="${y(v) + 4}" text-anchor="end">${v}</text>`;
    }
    cats.forEach((c, i) => {
      const cx = m.l + band * i + band / 2;
      const gw = bw * series.length + 2 * (series.length - 1);
      series.forEach((s, j) => {
        const x = cx - gw / 2 + j * (bw + 2);
        g += `<path d="${barPath(x, y(0), bw, y(0) - y(s.values[i]), true)}" fill="${s.color}"/>`;
      });
      if (cats.length <= 16 || i % 2 === 0) g += `<text x="${cx}" y="${H - 8}" text-anchor="middle">${esc(c.label)}</text>`;
      g += `<rect class="hit" x="${m.l + band * i}" y="${m.t}" width="${band}" height="${ih}" data-tt="${esc(c.tt)}"/>`;
    });
    return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(opts.label || "")}">${g}</svg>`;
  }

  // Diverging: positive values up (top series), negative down (bottom series).
  function divergingBars(cats, top, bottom, opts = {}) {
    const W = 640, H = opts.height || 240, m = { t: 12, r: 8, b: 24, l: 28 };
    const iw = W - m.l - m.r, ih = H - m.t - m.b;
    const max = niceMax(Math.max(1, ...top.values, ...bottom.values));
    const mid = m.t + ih / 2;
    const sc = (v) => (v / max) * (ih / 2);
    const band = iw / Math.max(cats.length, 1);
    const bw = Math.min(30, band * 0.55);
    const step = max <= 10 ? (max <= 6 ? 2 : 4) : 5;
    let g = "";
    for (let v = step; v <= max; v += step) {
      g += `<line class="gridline" x1="${m.l}" x2="${W - m.r}" y1="${mid - sc(v)}" y2="${mid - sc(v)}"/>`;
      g += `<line class="gridline" x1="${m.l}" x2="${W - m.r}" y1="${mid + sc(v)}" y2="${mid + sc(v)}"/>`;
      g += `<text x="${m.l - 6}" y="${mid - sc(v) + 4}" text-anchor="end">${v}</text>`;
      g += `<text x="${m.l - 6}" y="${mid + sc(v) + 4}" text-anchor="end">${v}</text>`;
    }
    cats.forEach((c, i) => {
      const cx = m.l + band * i + band / 2, x = cx - bw / 2;
      g += `<path d="${barPath(x, mid - 1, bw, sc(top.values[i]), true)}" fill="${top.color}"/>`;
      g += `<path d="${barPath(x, mid + 1, bw, sc(bottom.values[i]), false)}" fill="${bottom.color}"/>`;
      if (cats.length <= 16 || i % 2 === 0) g += `<text x="${cx}" y="${H - 6}" text-anchor="middle">${esc(c.label)}</text>`;
      g += `<rect class="hit" x="${m.l + band * i}" y="${m.t}" width="${band}" height="${ih}" data-tt="${esc(c.tt)}"/>`;
    });
    g += `<line class="axis" x1="${m.l}" x2="${W - m.r}" y1="${mid}" y2="${mid}"/>`;
    return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(opts.label || "")}">${g}</svg>`;
  }
  const legend = (items) => `<div class="chart-legend">${items.map(([n, c]) => `<span><i style="background:${c}"></i>${esc(n)}</span>`).join("")}</div>`;

  // ---------- leaderboards ----------
  function rankRows(rows, key, desc = true) {
    const sorted = [...rows].sort((a, b) => (desc ? b[key] - a[key] : a[key] - b[key]) || a.presenze - b.presenze || a.giocatore.localeCompare(b.giocatore));
    let last = null, rank = 0;
    sorted.forEach((r, i) => { if (r[key] !== last) { rank = i + 1; last = r[key]; } r._rank = rank; });
    return sorted;
  }
  const BOARDS = {
    generale: { label: "Generale", key: "punti", unit: "pt" },
    marcatori: { label: "Marcatori", key: "gol", unit: "gol" },
    assist: { label: "Assist", key: "assist", unit: "assist" },
    ga: { label: "Gol + Assist", key: "ga", unit: "G+A" },
    presenze: { label: "Presenze", key: "presenze", unit: "pres." },
    portieri: { label: "Portieri", key: "media_subiti", unit: "gs/p", asc: true },
    nera: { label: "Maglia nera", key: "sconfitte", unit: "sconf." },
  };
  function boardRows(id) {
    const rows = standings().filter((r) => r.presenze > 0).map((r) => ({
      ...r, ga: r.gol + r.assist,
      media_subiti: r.presenze_porta ? r.gol_subiti_in_porta / r.presenze_porta : 0,
    }));
    if (id === "generale") return rows.map((r) => ({ ...r, _rank: r.posizione }));
    if (id === "portieri") return rankRows(rows.filter((r) => r.presenze_porta > 0), "media_subiti", false);
    return rankRows(rows.filter((r) => r[BOARDS[id].key] > 0), BOARDS[id].key);
  }
  function boardValue(id, r) {
    if (id === "portieri") return fmt1(r.media_subiti);
    return r[BOARDS[id].key];
  }
  function podium(id, rows) {
    const top = rows.slice(0, 3);
    if (!top.length) return "";
    const order = [top[1], top[0], top[2]];
    return `<div class="podium">${order.map((r, k) => {
      if (!r) return "<div></div>";
      const p = players.get(r.id_giocatore), cls = k === 1 ? "p1" : "p" + (k === 0 ? 2 : 3);
      return `<a class="pod ${cls}" href="#/giocatore/${r.id_giocatore}"><span class="pod-rank">${r._rank}°</span>${avatar(p)}
        <div class="pod-name">${esc(fullName(p))}</div>${nick(p, "pod-nick")}
        <div class="pod-val">${boardValue(id, r)}<small>${BOARDS[id].unit}</small></div></a>`;
    }).join("")}</div>`;
  }
  function boardTable(id, rows) {
    if (!rows.length) return `<div class="empty">Nessun dato ancora per questa classifica.</div>`;
    let head, cells;
    if (id === "generale") {
      head = `<th></th><th class="l">Giocatore</th><th title="Partite giocate">PG</th><th>V</th><th>P</th><th>S</th><th title="Gol fatti dalla squadra">GF</th><th title="Gol subiti dalla squadra">GS</th><th title="Differenza reti">DR</th><th>Forma</th><th>Pt</th>`;
      cells = (r) => `<td>${r.presenze}</td><td>${r.vittorie}</td><td>${r.pareggi}</td><td>${r.sconfitte}</td><td>${r.gol_squadra}</td><td>${r.gol_subiti}</td><td>${r.differenza_reti > 0 ? "+" : ""}${r.differenza_reti}</td><td>${form(r.id_giocatore)}</td><td class="pts">${r.punti}</td>`;
    } else if (id === "portieri") {
      head = `<th></th><th class="l">Giocatore</th><th>In porta</th><th>Gol subiti</th><th>Media subiti</th><th>Parate miracolose</th>`;
      cells = (r) => `<td>${r.presenze_porta}</td><td>${r.gol_subiti_in_porta}</td><td class="pts">${fmt1(r.media_subiti)}</td><td>${r.parate_miracolose}</td>`;
    } else {
      const k = BOARDS[id].key;
      head = `<th></th><th class="l">Giocatore</th><th>PG</th><th>Gol</th><th>Assist</th><th>Media gol</th><th>${esc(BOARDS[id].label)}</th>`;
      cells = (r) => `<td>${r.presenze}</td><td>${r.gol}</td><td>${r.assist}</td><td>${fmt1(r.gol / r.presenze)}</td><td class="pts">${r[k]}</td>`;
    }
    return `<div class="table-wrap"><table><thead><tr>${head}</tr></thead><tbody>${rows.map((r, i) => {
      const p = players.get(r.id_giocatore);
      return `<tr class="link ${r._rank === 1 ? "top1" : ""}" onclick="location.hash='#/giocatore/${r.id_giocatore}'"><td class="pos">${i > 0 && rows[i - 1]._rank === r._rank ? "" : r._rank}</td><td class="l">${who(p)}</td>${cells(r)}</tr>`;
    }).join("")}</tbody></table></div>`;
  }
  function boardsBlock(active, withPodium = true) {
    const rows = boardRows(active);
    return `<div class="tabs">${Object.entries(BOARDS).map(([k, b]) =>
      `<button class="tab ${k === active ? "active" : ""}" data-board="${k}">${b.label}</button>`).join("")}</div>
      ${withPodium ? podium(active, rows) : ""}
      <div class="panel">${boardTable(active, rows)}</div>
      ${active === "generale" ? `<div class="note">Ordinamento: punti → differenza reti → gol segnati → meno presenze. Punti: vittoria ${D.regole.punti_vittoria}, pareggio ${D.regole.punti_pareggio}, sconfitta ${D.regole.punti_sconfitta}.</div>` : ""}
      ${active === "portieri" ? `<div class="note">Media dei gol subiti nelle partite giocate in porta (più bassa = meglio).</div>` : ""}`;
  }
  function wireBoards(root, rerender) {
    root.querySelectorAll("[data-board]").forEach((b) => b.addEventListener("click", () => rerender(b.dataset.board)));
  }

  // ---------- shared fragments ----------
  function scoreboard(m, link) {
    const A = m.gol_A, B = m.gol_B;
    const tag = link ? "a" : "div";
    const cA = teamColor(m, "A"), cB = teamColor(m, "B");
    return `<${tag} class="panel scoreboard" style="--ca:${cA};--cb:${cB}" ${link ? `href="#/partita/${m.id_partita}"` : ""}>
      <div class="sb-team a"><div class="sb-crest a">${crestLetter(m, "A")}</div><div><div class="sb-name">${esc(teamName(m, "A"))}</div><div class="sb-tag">${m.vincitore === "A" ? "Vincitori" : m.vincitore === "X" ? "Pareggio" : "&nbsp;"}</div></div></div>
      <div class="sb-score"><span class="n ${A > B ? "win" : ""}">${A}</span><span class="sep">–</span><span class="n ${B > A ? "win" : ""}">${B}</span></div>
      <div class="sb-team b"><div><div class="sb-name">${esc(teamName(m, "B"))}</div><div class="sb-tag">${m.vincitore === "B" ? "Vincitori" : m.vincitore === "X" ? "Pareggio" : "&nbsp;"}</div></div><div class="sb-crest b">${crestLetter(m, "B")}</div></div>
      <div class="sb-meta"><span class="pill">Giornata ${matchNo(m)}</span><span class="pill">${fmtDate(m.data)}</span>${m.luogo ? `<span class="pill">${esc(m.luogo)}</span>` : ""}<span class="pill">Stagione ${esc(m.stagione)}</span></div>
    </${tag}>`;
  }
  function matchRow(m) {
    return `<a class="match-row" href="#/partita/${m.id_partita}">
      <div class="mr-date">${fmtDate(m.data, { day: "numeric", month: "short" })}<small>G${matchNo(m)}</small></div>
      <div class="mr-team">${teamDot(m, "A")}${esc(teamName(m, "A"))}</div>
      <div class="mr-score">${m.gol_A} – ${m.gol_B}</div>
      <div class="mr-team b">${esc(teamName(m, "B"))}${teamDot(m, "B")}</div>
      <div class="mr-arrow">›</div></a>`;
  }
  // Declared habitual role, otherwise the role played most often.
  function mainRole(pid) {
    const p = players.get(pid);
    if (p.ruolo_abituale) return p.ruolo_abituale;
    const c = {};
    apps.filter((a) => a.id_giocatore === pid).forEach((a) => (c[a.ruolo] = (c[a.ruolo] || 0) + 1));
    return Object.keys(c).sort((a, b) => c[b] - c[a] || ri(a) - ri(b))[0] || "";
  }
  function pcard(pid) {
    const p = players.get(pid), r = standings().find((x) => x.id_giocatore === pid) || {};
    const gk = p.ruolo_abituale === "P";
    return `<a class="pcard ${p.attivo === "0" ? "inactive" : ""}" href="#/giocatore/${pid}">
      <span class="pcard-role ${gk ? "gk" : ""}" title="${esc(roleName(mainRole(pid)))}">${roleShort(mainRole(pid)) || "—"}</span>
      ${avatar(p)}<div class="pcard-name">${esc(fullName(p))}</div>
      <div class="pcard-nick">${p.soprannome ? "“" + esc(p.soprannome) + "”" : ""}</div>
      <div class="pcard-stats"><div>${r.presenze || 0}<small>PG</small></div><div>${r.gol || 0}<small>GOL</small></div><div>${r.punti || 0}<small>PT</small></div></div></a>`;
  }

  // ---------- pages ----------
  function pageHome() {
    const ms = seasonMatches(), sa = seasonApps();
    const goals = ms.reduce((s, m) => s + m.gol_A + m.gol_B, 0);
    const used = new Set(sa.map((a) => a.id_giocatore)).size;
    const last = ms[ms.length - 1];
    const leader = (id) => boardRows(id)[0];
    const leaders = [
      ["Capocannoniere", "marcatori", (r) => `${r.gol} gol`],
      ["Re degli assist", "assist", (r) => `${r.assist} assist`],
      ["Stakanovista", "presenze", (r) => `${r.presenze} presenze`],
      ["Saracinesca", "portieri", (r) => `${fmt1(r.media_subiti)} gol subiti a partita`],
    ];
    const html = `
      <div class="hero-kicker">Stagione ${esc(season)}</div>
      <h1 class="hero-title">Calcetto <span>Archeologico</span></h1>
      <div class="grid g4 section" style="margin-top:22px">
        <div class="panel kpi"><div class="kpi-label">Partite giocate</div><div class="kpi-value">${ms.length}</div><div class="kpi-foot">${last ? "ultima: " + fmtDate(last.data, { day: "numeric", month: "long" }) : "—"}</div></div>
        <div class="panel kpi"><div class="kpi-label">Gol segnati</div><div class="kpi-value">${goals}</div><div class="kpi-foot">${ms.length ? fmt1(goals / ms.length) + " a partita" : "—"}</div></div>
        <div class="panel kpi"><div class="kpi-label">Giocatori scesi in campo</div><div class="kpi-value">${used}<span class="muted" style="font-size:24px"> / ${players.size}</span></div><div class="kpi-foot">in rosa</div></div>
        <div class="panel kpi"><div class="kpi-label">Presenze totali</div><div class="kpi-value">${sa.length}</div><div class="kpi-foot">${ms.length ? fmt1(sa.length / ms.length) + " giocatori a partita" : "—"}</div></div>
      </div>
      ${last ? `<div class="section"><div class="section-head"><h2 class="section-title">Ultima partita</h2></div>${scoreboard(last, true)}</div>` : ""}
      <div class="section"><div class="section-head"><h2 class="section-title">I leader</h2></div>
        <div class="grid g4">${leaders.map(([t, id, f]) => {
          const r = leader(id);
          if (!r) return `<div class="panel"><div class="syn-kicker">${t}</div><div class="empty">—</div></div>`;
          const p = players.get(r.id_giocatore);
          return `<a class="panel syn-best" href="#/giocatore/${r.id_giocatore}">${avatar(p)}<div><div class="syn-kicker">${t}</div><div class="syn-name">${esc(fullName(p))}</div>${nick(p, "syn-nick")}<div class="syn-val">${f(r)}</div></div></a>`;
        }).join("")}</div>
      </div>
      <div class="section"><div class="section-head"><h2 class="section-title">Classifica</h2><span class="section-sub">Tutte le classifiche nella pagina dedicata</span></div>
        <div id="boards"></div></div>`;
    $app.innerHTML = html;
    const host = $app.querySelector("#boards");
    const render = (id) => { host.innerHTML = boardsBlock(id, false); wireBoards(host, render); };
    render("generale");
  }

  function pageBoards(active = "generale") {
    $app.innerHTML = `<div class="hero-kicker">Stagione ${esc(season)}</div><h1 class="hero-title">Classifiche</h1><div class="section" id="boards"></div>`;
    const host = $app.querySelector("#boards");
    const render = (id) => { host.innerHTML = boardsBlock(id, true); wireBoards(host, render); };
    render(active);
  }

  function pageMatches() {
    const ms = [...seasonMatches()].reverse();
    $app.innerHTML = `<div class="hero-kicker">Stagione ${esc(season)}</div><h1 class="hero-title">Partite</h1>
      <div class="section">${ms.length ? ms.map(matchRow).join("") : `<div class="empty">Nessuna partita.</div>`}</div>`;
  }

  function pageRoster() {
    const st = standings();
    const ids = [...players.keys()].sort((a, b) => {
      const ra = st.find((r) => r.id_giocatore === a) || {}, rb = st.find((r) => r.id_giocatore === b) || {};
      return (rb.presenze || 0) - (ra.presenze || 0) || players.get(a).cognome.localeCompare(players.get(b).cognome);
    });
    $app.innerHTML = `<div class="hero-kicker">Stagione ${esc(season)}</div><h1 class="hero-title">La rosa</h1>
      <div class="section grid roster">${ids.map(pcard).join("")}</div>`;
  }

  // Synergies of player pid in the current season.
  function synergies(pid) {
    const mine = appsOf(pid);
    const mates = new Map(), opps = new Map();
    const bump = (map, id, won, a) => {
      const s = map.get(id) || { id, n: 0, v: 0, gf: 0, gs: 0 };
      s.n++; s.v += won ? 1 : 0; s.gf += a.gol_squadra; s.gs += a.gol_subiti; map.set(id, s);
    };
    mine.forEach((a) => {
      appsOfMatch(a.id_partita).forEach((o) => {
        if (o.id_giocatore === pid) return;
        bump(o.squadra === a.squadra ? mates : opps, o.id_giocatore, a.esito === "V", a);
      });
    });
    const list = (map) => [...map.values()].map((s) => ({ ...s, pct: pct(s.v, s.n) }))
      .sort((a, b) => b.pct - a.pct || b.n - a.n);
    return { mates: list(mates), opps: list(opps) };
  }
  function synTable(rows, label) {
    if (!rows.length) return `<div class="empty">Nessun dato.</div>`;
    return `<table><thead><tr><th class="l">Giocatore</th><th>${label}</th><th>Vinte</th><th>% vittorie</th></tr></thead><tbody>${rows.map((s) => {
      const p = players.get(s.id);
      return `<tr class="link ${s.n < MIN_SYNERGY ? "dim" : ""}" onclick="location.hash='#/giocatore/${s.id}'"><td class="l">${who(p)}</td><td>${s.n}</td><td>${s.v}</td>
        <td><span class="bar-cell">${s.pct}%<span class="bar-track"><span class="bar-fill" style="width:${s.pct}%"></span></span></span></td></tr>`;
    }).join("")}</tbody></table>`;
  }

  function pagePlayer(pid) {
    const p = players.get(pid);
    if (!p) return pageNotFound();
    const r = standings().find((x) => x.id_giocatore === pid) || {};
    const my = appsOf(pid);
    const n = my.length;
    const syn = synergies(pid);
    const signif = (rows) => rows.filter((s) => s.n >= MIN_SYNERGY);
    const bestMate = (signif(syn.mates)[0]) || syn.mates[0];
    const nemesis = [...(signif(syn.opps).length ? signif(syn.opps) : syn.opps)].sort((a, b) => a.pct - b.pct || b.n - a.n)[0];
    const lowSample = !signif(syn.mates).length;

    const cats = my.map((a) => {
      const m = matchById.get(a.id_partita);
      return {
        label: shortDate(a.data),
        tt: `<b>G${matchNo(m)} · ${fmtDate(a.data)}</b><div class="tt-row"><span>Risultato</span><span>${a.gol_squadra}–${a.gol_subiti} (${{ V: "vinta", X: "pari", S: "persa" }[a.esito]})</span></div><div class="tt-row"><span>Gol</span><span>${a.gol}</span></div><div class="tt-row"><span>Assist</span><span>${a.assist}</span></div>${a.ruolo === "P" ? `<div class="tt-row"><span>In porta</span><span>sì</span></div>` : ""}`,
      };
    });

    $app.innerHTML = `
      <a class="back" href="#/giocatori">‹ La rosa</a>
      <div class="phero">
        <div class="fut">
          <div class="fut-top"><div class="fut-rating">${r.posizione ? r.posizione + "°" : "–"}<small>IN CLASSIFICA</small></div><div class="fut-rating" style="text-align:right">${r.punti || 0}<small>PUNTI</small></div></div>
          ${avatar(p)}
          <div class="fut-name">${esc(fullName(p))}</div>
          <div class="fut-nick">${p.soprannome ? "“" + esc(p.soprannome) + "”" : "&nbsp;"}</div><div class="muted" style="font:600 13px/1.4 var(--cond);letter-spacing:1.5px;text-transform:uppercase">${esc(mainRole(pid) ? roleName(mainRole(pid)) : "")}</div>
          <div class="fut-stats">
            <div>${r.presenze || 0}<small>PRESENZE</small></div><div>${r.gol || 0}<small>GOL</small></div><div>${r.assist || 0}<small>ASSIST</small></div>
            <div>${n ? pct(r.vittorie, n) + "%" : "–"}<small>VITTORIE</small></div><div>${n ? fmt1(r.gol / n) : "–"}<small>GOL/PARTITA</small></div><div>${r.parate_miracolose || 0}<small>PARATE</small></div>
          </div>
        </div>
        <div class="phero-side">
          <div class="grid g3">
            <div class="panel kpi"><div class="kpi-label">Bilancio</div><div class="kpi-value">${r.vittorie || 0}-${r.pareggi || 0}-${r.sconfitte || 0}</div><div class="kpi-foot">vittorie · pareggi · sconfitte</div></div>
            <div class="panel kpi"><div class="kpi-label">Gol squadra</div><div class="kpi-value">${r.gol_squadra || 0}<span class="muted" style="font-size:26px"> / ${r.gol_subiti || 0}</span></div><div class="kpi-foot">fatti / subiti con lui in campo</div></div>
            <div class="panel kpi"><div class="kpi-label">Differenza reti</div><div class="kpi-value">${(r.differenza_reti || 0) > 0 ? "+" : ""}${r.differenza_reti || 0}</div><div class="kpi-foot">${r.autogol ? r.autogol + " autogol" : "nessun autogol"}</div></div>
          </div>
          <div class="panel"><div class="kpi-label" style="margin-bottom:10px">Forma (ultime 5)</div>${n ? `<span class="form">${my.slice(-5).map((a) => chip(a.esito, true)).join("")}</span>` : `<span class="muted">Non ha ancora giocato.</span>`}</div>
          <div class="grid g2">
            <div class="panel syn-best">${bestMate ? avatar(players.get(bestMate.id)) + `<div><div class="syn-kicker">Miglior compagno</div><div class="syn-name">${esc(fullName(players.get(bestMate.id)))}</div>${nick(players.get(bestMate.id), "syn-nick")}<div class="syn-val">${bestMate.v}/${bestMate.n} vinte insieme (${bestMate.pct}%)</div></div>` : `<div><div class="syn-kicker">Miglior compagno</div><div class="empty">—</div></div>`}</div>
            <div class="panel syn-best">${nemesis ? avatar(players.get(nemesis.id)) + `<div><div class="syn-kicker">Bestia nera</div><div class="syn-name">${esc(fullName(players.get(nemesis.id)))}</div>${nick(players.get(nemesis.id), "syn-nick")}<div class="syn-val">${nemesis.v}/${nemesis.n} vinte contro (${nemesis.pct}%)</div></div>` : `<div><div class="syn-kicker">Bestia nera</div><div class="empty">—</div></div>`}</div>
          </div>
          ${lowSample && n ? `<div class="note" style="margin-top:0">Campione ancora piccolo: le sinergie diventano significative da ${MIN_SYNERGY} partite insieme.</div>` : ""}
        </div>
      </div>

      ${n ? `
      <div class="grid g2 section">
        <div class="panel"><h3 class="section-title" style="font-size:20px">Gol e assist per partita</h3>
          ${legend([["Gol", COLORS.gol], ["Assist", COLORS.assist]])}
          ${groupedBars(cats, [{ name: "Gol", color: COLORS.gol, values: my.map((a) => a.gol) }, { name: "Assist", color: COLORS.assist, values: my.map((a) => a.assist) }], { label: "Gol e assist per partita" })}
        </div>
        <div class="panel"><h3 class="section-title" style="font-size:20px">Gol fatti e subiti</h3>
          ${legend([["Fatti dalla sua squadra ↑", COLORS.fatti], ["Subiti ↓", COLORS.subiti]])}
          ${divergingBars(cats, { color: COLORS.fatti, values: my.map((a) => a.gol_squadra) }, { color: COLORS.subiti, values: my.map((a) => a.gol_subiti) }, { label: "Gol fatti e subiti dalla squadra per partita" })}
        </div>
      </div>

      <div class="grid g2 section">
        <div class="panel"><h3 class="section-title" style="font-size:20px">Con chi vince</h3><div class="section-sub" style="margin:4px 0 8px">Partite giocate nella stessa squadra</div><div class="table-wrap">${synTable(syn.mates, "Insieme")}</div></div>
        <div class="panel"><h3 class="section-title" style="font-size:20px">Contro chi vince</h3><div class="section-sub" style="margin:4px 0 8px">Partite giocate da avversari</div><div class="table-wrap">${synTable(syn.opps, "Contro")}</div></div>
      </div>

      <div class="section"><div class="section-head"><h2 class="section-title">Partite giocate</h2></div>
        <div class="panel table-wrap"><table><thead><tr><th class="l">Data</th><th class="l">Squadra</th><th class="l">Ruolo</th><th>Risultato</th><th>Esito</th><th class="l">Statistiche</th></tr></thead><tbody>
        ${[...my].reverse().map((a) => {
          const m = matchById.get(a.id_partita);
          return `<tr class="link" onclick="location.hash='#/partita/${a.id_partita}'"><td class="l">${fmtDate(a.data)}</td><td class="l"><span class="mr-team" style="font-size:15px">${teamDot(m, a.squadra)}${esc(teamName(m, a.squadra))}</span></td><td class="l">${roleName(a.ruolo)}</td><td>${a.gol_squadra} – ${a.gol_subiti}</td><td>${chip(a.esito)}</td><td class="l"><span class="lu-icons">${statIcons(a) || '<span class="muted">—</span>'}</span></td></tr>`;
        }).join("")}</tbody></table></div></div>` : `<div class="section empty">Nessuna presenza in questa stagione.</div>`}`;
    bindTooltips($app);
  }

  // Pitch layout: each team in its own half; team A attacks right, B attacks left.
  // Role slots are given for team A (x, y on a 1000x600 pitch); team B is
  // mirrored on both axes so "left" midfielders sit on the team's own left.
  const SLOTS = { P: [75, 300], D: [195, 300], MS: [315, 135], MD: [315, 465], A: [420, 300] };
  function layoutTeam(list, side) {
    const W = 1000, H = 600, pos = [];
    const groups = {};
    list.forEach((a) => (groups[SLOTS[a.ruolo] ? a.ruolo : "?"] ||= []).push(a));
    Object.entries(groups).forEach(([r, arr]) => {
      const [bx, by] = SLOTS[r] || [300, 300];
      arr.forEach((a, i) => {
        // several players with the same role: fan them out vertically
        const y = Math.max(70, Math.min(H - 90, by + (i - (arr.length - 1) / 2) * 130));
        pos.push([a, bx, y]);
      });
    });
    return pos.map(([a, x, y]) => (side === "A" ? [a, x, y] : [a, W - x, H - y]));
  }
  function pitch(m) {
    const list = appsOfMatch(m.id_partita);
    const W = 1000, H = 600;
    let stripes = "";
    for (let i = 0; i < 10; i++) stripes += `<rect x="${i * 100}" y="0" width="100" height="${H}" fill="${i % 2 ? "#1f6b3a" : "#237540"}"/>`;
    const L = `stroke="rgba(255,255,255,.7)" stroke-width="3" fill="none"`;
    const field = `${stripes}
      <rect x="20" y="20" width="${W - 40}" height="${H - 40}" ${L}/>
      <line x1="${W / 2}" y1="20" x2="${W / 2}" y2="${H - 20}" ${L}/>
      <circle cx="${W / 2}" cy="${H / 2}" r="70" ${L}/><circle cx="${W / 2}" cy="${H / 2}" r="4" fill="rgba(255,255,255,.8)"/>
      <path d="M20,${H / 2 - 150} A150,150 0 0 1 20,${H / 2 + 150}" ${L}/>
      <path d="M${W - 20},${H / 2 - 150} A150,150 0 0 0 ${W - 20},${H / 2 + 150}" ${L}/>
      <rect x="2" y="${H / 2 - 50}" width="18" height="100" ${L}/><rect x="${W - 20}" y="${H / 2 - 50}" width="18" height="100" ${L}/>`;
    const tokens = ["A", "B"].flatMap((t) => layoutTeam(list.filter((a) => a.squadra === t), t)).map(([a, x, y]) => {
      const p = players.get(a.id_giocatore);
      const col = teamColor(m, a.squadra);
      const cid = "c-" + a.id_giocatore;
      const photo = p.foto ? `<clipPath id="${cid}"><circle cx="${x}" cy="${y}" r="30"/></clipPath><image href="${esc(p.foto)}" x="${x - 30}" y="${y - 30}" width="60" height="60" clip-path="url(#${cid})" preserveAspectRatio="xMidYMid slice"/>` : "";
      const badgeTxt = statList(a).map((s) => s.icon + s.n).join(" ");
      const bw = badgeTxt ? 14 + badgeTxt.length * 9 : 0;
      const tip = statTooltip(a, p);
      return `<g class="pl-token" data-tt="${esc(tip)}" onclick="location.hash='#/giocatore/${a.id_giocatore}'">
        <circle cx="${x}" cy="${y + 3}" r="33" fill="rgba(0,0,0,.25)"/>
        <circle cx="${x}" cy="${y}" r="30" fill="#14204a"/>
        <text x="${x}" y="${y + 8}" text-anchor="middle" font-family="Barlow Condensed, Arial Narrow, sans-serif" font-weight="800" font-size="22" fill="#fff">${esc(initials(p))}</text>
        ${photo}
        <circle class="ring" cx="${x}" cy="${y}" r="30" fill="none" stroke="${a.ruolo === "P" ? "#f5c518" : col}" stroke-width="4"/>
        <rect x="${x - 58}" y="${y + 38}" width="116" height="24" rx="6" fill="rgba(6,11,28,.85)"/>
        <text x="${x}" y="${y + 55}" text-anchor="middle" font-family="Barlow Condensed, Arial Narrow, sans-serif" font-weight="700" font-size="16" fill="#fff">${esc(p.cognome.toUpperCase())}</text>
        ${badgeTxt ? `<rect x="${x + 16}" y="${y - 44}" width="${bw}" height="22" rx="11" fill="#fff"/><text x="${x + 16 + bw / 2}" y="${y - 28}" text-anchor="middle" font-size="14" font-weight="700" fill="#0a1128">${badgeTxt}</text>` : ""}
      </g>`;
    }).join("");
    return `<svg class="pitch-svg" viewBox="0 0 ${W} ${H}" role="img" aria-label="Formazioni in campo">${field}${tokens}</svg>`;
  }

  const ri = (r) => { const i = ROLE_ORDER.indexOf(r); return i < 0 ? 99 : i; };
  function lineup(m, t) {
    const list = appsOfMatch(m.id_partita).filter((a) => a.squadra === t)
      .sort((a, b) => ri(a.ruolo) - ri(b.ruolo) || b.gol - a.gol || b.assist - a.assist);
    return `<div class="panel"><div class="lineup-head">${teamDot(m, t, "width:14px;height:14px")}${esc(teamName(m, t))}<span class="muted" style="margin-left:auto;font-size:28px;font-style:normal">${m["gol_" + t]}</span></div>
      ${list.map((a) => {
        const p = players.get(a.id_giocatore);
        return `<a class="lu-row" href="#/giocatore/${a.id_giocatore}"><span class="lu-role">${roleShort(a.ruolo)}</span>${avatar(p)}<span class="lu-name">${esc(fullName(p))}${nick(p)}</span><span class="lu-icons">${statIcons(a)}</span></a>`;
      }).join("")}</div>`;
  }

  function pageMatch(mid) {
    const m = matchById.get(mid);
    if (!m) return pageNotFound();
    const list = appsOfMatch(mid);
    const scorers = (t) => list.filter((a) => a.squadra === t && a.gol).sort((a, b) => b.gol - a.gol)
      .map((a) => `${esc(players.get(a.id_giocatore).cognome)}${a.gol > 1 ? " " + a.gol : ""}`).join(", ");
    const ogs = list.filter((a) => a.autogol);
    const mvpScore = (a) => 2 * a.gol + 1.5 * a.assist + 2 * a.parate_miracolose - 2 * a.autogol + (a.esito === "V" ? 1 : 0);
    const mvp = [...list].sort((a, b) => mvpScore(b) - mvpScore(a))[0];
    const sm = seasonMatchesOf(m.stagione), i = sm.indexOf(m);
    const prev = sm[i - 1], next = sm[i + 1];

    $app.innerHTML = `
      <a class="back" href="#/partite">‹ Tutte le partite</a>
      ${scoreboard(m, false)}
      <div class="grid g2" style="margin-top:12px">
        <div class="panel"><div class="kpi-label">Marcatori</div>
          <div style="margin-top:8px">${teamDot(m, "A", "display:inline-block")} ${scorers("A") || "—"}</div>
          <div>${teamDot(m, "B", "display:inline-block")} ${scorers("B") || "—"}</div>
          ${ogs.length ? `<div class="muted" style="margin-top:4px">Autogol: ${ogs.map((a) => esc(players.get(a.id_giocatore).cognome)).join(", ")}</div>` : ""}
        </div>
        ${mvp ? `<a class="panel syn-best" href="#/giocatore/${mvp.id_giocatore}">${avatar(players.get(mvp.id_giocatore))}<div><div class="syn-kicker">⭐ Migliore in campo</div><div class="syn-name">${esc(fullName(players.get(mvp.id_giocatore)))}</div>${nick(players.get(mvp.id_giocatore), "syn-nick")}<div class="syn-val">${mvp.gol} gol · ${mvp.assist} assist${mvp.parate_miracolose ? " · " + mvp.parate_miracolose + " parate" : ""}</div></div></a>` : ""}
      </div>
      <div class="section"><div class="section-head"><h2 class="section-title">In campo</h2></div>
        <div class="pitch-wrap">${pitch(m)}</div>
        <div class="legend"><span>${teamDot(m, "A")}${esc(teamName(m, "A"))}</span><span>${teamDot(m, "B")}${esc(teamName(m, "B"))}</span><span>Bordo oro = portiere</span><span>⚽ gol</span><span>👟 assist</span><span>🧤 parate miracolose</span><span>🔴 autogol</span><span>🥅 pali e traverse</span></div>
      </div>
      <div class="section"><div class="section-head"><h2 class="section-title">Tabellino</h2></div>
        <div class="grid g2">${lineup(m, "A")}${lineup(m, "B")}</div>
        <div class="note">Migliore in campo calcolato: 2×gol + 1,5×assist + 2×parate miracolose − 2×autogol, +1 se ha vinto.</div>
      </div>
      <div class="pager">${prev ? `<a href="#/partita/${prev.id_partita}">‹ ${fmtDate(prev.data, { day: "numeric", month: "short" })}</a>` : "<span></span>"}${next ? `<a href="#/partita/${next.id_partita}">${fmtDate(next.data, { day: "numeric", month: "short" })} ›</a>` : "<span></span>"}</div>`;
    bindTooltips($app);
  }

  function pageNotFound() {
    $app.innerHTML = `<h1 class="hero-title">Fuorigioco!</h1><p class="muted">Pagina non trovata. <a href="#/" style="color:var(--lime)">Torna alla home</a></p>`;
  }

  // ---------- router ----------
  function route() {
    const h = location.hash.replace(/^#\/?/, "");
    const [page, arg] = h.split("/");
    document.querySelectorAll(".nav a").forEach((a) => a.classList.toggle("active", a.dataset.page === (page || "home")
      || (a.dataset.page === "giocatori" && page === "giocatore") || (a.dataset.page === "partite" && page === "partita")));
    tt.style.opacity = 0;
    if (!page) pageHome();
    else if (page === "classifiche") pageBoards(arg);
    else if (page === "partite") pageMatches();
    else if (page === "giocatori") pageRoster();
    else if (page === "giocatore") pagePlayer(decodeURIComponent(arg || ""));
    else if (page === "partita") pageMatch(decodeURIComponent(arg || ""));
    else pageNotFound();
    window.scrollTo(0, 0);
  }

  // Season selector (shown only when more than one season exists).
  const sel = document.getElementById("season");
  if (seasons.length > 1) {
    sel.innerHTML = seasons.map((s) => `<option ${s === season ? "selected" : ""}>${esc(s)}</option>`).join("");
    sel.hidden = false;
    sel.addEventListener("change", () => { season = sel.value; route(); });
  }
  document.getElementById("brand-season").textContent = season.replace("-", "/");
  window.addEventListener("hashchange", route);
  route();
})();
